//! Full hidden-inclusive CODE declaration policy over borrowed original pages.
//! Native authored headers supplement the same original text policy; no Tree/model copy.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_file::{Config,RawPolicyViews},reactive_raw_policy_pages::RawPolicyPages,decl_policy::{self,Decl},captured_allow_annotations::PatternOperation,key_policy_control::{self as kc,Control},lint::{Site,AllowUse}};
use std::{collections::{BTreeMap,BTreeSet},io,path::Path,sync::Arc};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}check(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
pub struct DeclData{sites:Vec<Site>,source_text:Vec<String>,allows:Vec<AllowUse>,digests:BTreeMap<String,[u8;20]>}
impl DeclData{
 pub fn metadata(&self)->&'static crate::lint::Meta{crate::lints::decl::captured_metadata()}
 pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allows}pub fn notes(&self)->&[String]{&[]}pub fn allow_source_digest(&self,relative:&str)->Option<&[u8;20]>{self.digests.get(relative)}
 pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(4)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.source_text)?;rows.serialize_element(&self.allows)?;rows.serialize_element(&self.digests)?;rows.end()}
 pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allows.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?;for s in &self.sites{for word in [&s.rule,&s.rel,&s.msg,&s.key,&s.ident]{n=n.checked_add(word.capacity())?}}for word in &self.source_text{n=n.checked_add(word.capacity())?}for a in &self.allows{for word in [&a.rel,&a.name,&a.code]{n=n.checked_add(word.capacity())?}}for path in self.digests.keys(){n=n.checked_add(2048)?.checked_add(path.capacity())?}Some(n)}
}
pub fn metadata()->&'static crate::lint::Meta{crate::lints::decl::captured_metadata()}
pub fn selects_path(relative:&str)->bool{relative.starts_with("code/")&&relative.ends_with(".dm")}
fn kept(data:&mut DeclData,file:&crate::tree::SourceFile,line:usize,local:&Budget,keep:&Budget,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<bool,Failure>{
 let mut work=PatternOperation{budget:local,poll,patterns};let raw=file.raw();let mut found=None;for current in [Some(line),line.checked_sub(1).filter(|n|*n!=0)].into_iter().flatten(){work.checkpoint()?;if current==0||current>raw.num_lines(){continue}if current!=line&&!crate::util::py_lstrip(raw.line(current)).starts_with("//"){continue}if let Some(code)=crate::allow::keeps_with(raw.line(current),"decl",&mut work)?{found=Some((current,code.unwrap_or_default()));break}}
 let Some((line,code))=found else{return Ok(false)};let mut held=PatternOperation{budget:keep,poll,patterns};if !data.allows.iter().any(|a|a.rel==file.rel&&a.line as usize==line&&a.name=="decl"&&a.code==code){kc::row(&mut held,&mut data.allows)?;keep.charge(code.capacity()).map_err(|m|oom(keep,m))?;data.allows.push(AllowUse{rel:kc::own(&mut held,&file.rel)?,line:u32::try_from(line).map_err(|_|oom(keep,"decl ALLOW line overflow"))?,name:kc::own(&mut held,"decl")?,code})}if !data.digests.contains_key(&file.rel){kc::reserve(&mut held,||Some(2048))?;data.digests.insert(kc::own(&mut held,&file.rel)?,crate::captured_raw_file::source_allow_digest(file));}Ok(true)
}
/// Two concrete raw phases: all hidden-inclusive CODE facts, then selected CODE judgments.
/// Completion and current source authority remain in the host-private exhausted loops.
pub fn collect_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<DeclData,Failure>{collect_using(inputs,root_path,pages,config,root,poll,None)}
pub fn collect_from_pages_with_patterns(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<DeclData,Failure>{collect_using(inputs,root_path,pages,config,root,poll,Some(patterns))}
fn collect_using(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<DeclData,Failure>{
 check(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&phase.budget;let pending=(||{
 let mut work=PatternOperation{budget,poll,patterns};let mut refs=BTreeSet::new();let all=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selects_path(relative){return Err("decl original source provider escaped hidden-inclusive CODE".into())}let file=views.source_file()?;let mut temp=PatternOperation{budget:local,poll,patterns};for name in decl_policy::owned_vars_using(file,&mut temp)?{work.checkpoint()?;if !refs.contains(&name){kc::reserve(&mut work,||Some(2048))?;budget.charge(name.capacity()).map_err(|m|oom(budget,m))?;refs.insert(name);}}Ok(true)})();finish(pending,local,poll)})?;if !all{return Err("decl facts stopped before hidden-inclusive CODE EOF".into())}
 let mut data=DeclData{sites:Vec::new(),source_text:Vec::new(),allows:Vec::new(),digests:BTreeMap::new()};
 kc::reserve(&mut work,||Some(std::mem::size_of::<Decl>()+4*14*std::mem::size_of::<(&str,crate::pat::Pat)>()+1024))?;let rules=if patterns.is_none(){Some(Decl::new())}else{None};let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{
 check(local,poll)?;if !selects_path(relative){return Err("decl selected source provider escaped hidden-inclusive CODE".into())}if config.policy_path_exempt("decl","",relative){return Ok(true)}let file=views.source_file()?;let mut temp=PatternOperation{budget:local,poll,patterns};let mut spans=Vec::new();let mut manual=BTreeSet::new();kc::reserve(&mut temp,||file.raw().num_lines().checked_mul(4*std::mem::size_of::<&str>())?.checked_add(128))?;let lines:Vec<_>=(1..=file.raw().num_lines()).map(|n|file.raw().line(n)).collect();
 dm_analysis::lifecycle_declarations::visit_lifecycle_definitions_using(inputs.archive(),dm_analysis::lifecycle_declarations::LifecyclePolicy::Decl,&||check(local,poll),&|error|Failure::Unsupported(error.0),&mut|row|{
  temp.checkpoint()?;let origin=inputs.archive().callable_header_policy_line(row.member)?;let actual=inputs.file_exact(origin.path.as_path()).ok_or("decl actual header is outside current source frame")?;if !actual.is_compiled(){return Err("decl actual header is not compiled source".into())}
  kc::reserve(&mut temp,||origin.path.as_os_str().len().checked_add(root_path.as_os_str().len())?.checked_mul(128)?.checked_add(4096))?;let Some(rel)=dm_preprocess::regions::relative_filesystem_path(origin.path.as_path(),root_path)else{return Ok(())};let rel=rel.to_string_lossy().replace('\\',"/");if rel!=relative{return Ok(())}let header=actual.analyze_display_line(origin.line).map_err(|error|Failure::Unsupported(error.to_string()))?;if header==0||header>file.raw().num_lines(){return Err("decl actual header line is outside original file".into())}
  let name=inputs.archive().tree().symbols().text(row.name).ok_or("decl actual callable name unavailable")?;if row.lifecycle{kc::row(&mut temp,&mut spans)?;spans.push((decl_policy::proc_kind(name),crate::lifecycle_source::body_lines_using(&lines,u32::try_from(header).map_err(|_|oom(local,"decl header overflow"))?,&mut temp)?));}else{kc::reserve(&mut temp,||Some(2048))?;manual.insert(header.checked_add(1).ok_or_else(||oom(local,"decl header boundary overflow"))?);}Ok(())
 })?;
 for span in decl_policy::text_spans_using(file,&mut temp)?{temp.checkpoint()?;if span.0!="Initialize"||!manual.contains(&span.1.start){kc::row(&mut temp,&mut spans)?;spans.push(span)}}
 let hits=if let Some(provider)=patterns{let scratch=Budget::scoped_temporaries(root).map_err(|message|oom(root,message))?;let fixture=crate::raw_fixture_policy::Fixture::scanned(&scratch,poll,provider,file).map_err(pattern_failure)?;let rules=Decl::with_fixture(&fixture);if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}let rules=rules.map_err(Failure::Unsupported)?;let pending=rules.judge_spans_using(file,&refs,&spans,&mut temp,&mut|line|kept(&mut data,file,line,local,budget,poll,patterns));if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}pending?}else{rules.as_ref().expect("actual compatibility declaration rules").judge_spans_using(file,&refs,&spans,&mut temp,&mut|line|kept(&mut data,file,line,local,budget,poll,patterns))?};
 for(rule,line)in hits{work.checkpoint()?;kc::row(&mut work,&mut data.sites)?;data.sites.push(Site{rule:kc::own(&mut work,data.metadata().rules[rule as usize].name)?,rel:kc::own(&mut work,relative)?,line,msg:String::new(),key:String::new(),ident:String::new()});kc::row(&mut work,&mut data.source_text)?;let text=file.raw().line(line as usize);kc::reserve(&mut work,||text.len().checked_mul(4)?.checked_add(128))?;data.source_text.push(crate::util::normalize_ws(text));}Ok(true)
 })();finish(pending,local,poll)})?;if !complete{return Err("decl judgment stopped before hidden-inclusive CODE EOF".into())}check(budget,poll)?;Ok(data)
 })();let pending=finish(pending,budget,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"decl retained backing overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)
}

fn pattern_failure(actual:crate::derived_selftest_policy::Failure)->Failure{match actual{crate::derived_selftest_policy::Failure::Operational(actual)=>Failure::Operational(actual),crate::derived_selftest_policy::Failure::Assertion(message)=>Failure::Unsupported(message)}}
